cd /tmp/vally-eval-trial-XfjFLn && cat > src/CheckoutPricing.Domain/LoyaltyDiscountPolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    public static int DiscountCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents * RatePercent(tier) / 100;

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null)
    };
}
EOF
cat > src/CheckoutPricing.Domain/DiscountPolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    private const int LoyaltyCapCents = 2_000;
    private const int LoyaltyMinimumSubtotalCents = 3_000;
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public static int TotalDiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyCents = LoyaltyCents(subtotalCents, tier);
        var promoCents = PromoCents(promoCode, subtotalCents - loyaltyCents);
        return Math.Min(subtotalCents, loyaltyCents + promoCents);
    }

    private static int LoyaltyCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < LoyaltyMinimumSubtotalCents
            ? 0
            : Math.Min(LoyaltyCapCents, LoyaltyDiscountPolicy.DiscountCents(subtotalCents, tier));

    private static int PromoCents(string? promoCode, int remainingCents)
    {
        if (Is(promoCode, "WELCOME5")) return Welcome5Cents;
        if (Is(promoCode, "SUMMER10")) return Math.Min(Summer10CapCents, remainingCents / 10);
        return 0;
    }

    private static bool Is(string? promoCode, string expected) =>
        string.Equals(promoCode, expected, StringComparison.OrdinalIgnoreCase);
}
EOF
cat > src/CheckoutPricing.Domain/ShippingPolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class ShippingPolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFee(tier) : StandardFee(payableTotalCents, tier);

    private static int ExpressFee(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFee(int payableTotalCents, LoyaltyTier tier) =>
        tier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromCents ? 0 : StandardFeeCents;
}
EOF
cat > src/CheckoutPricing.Application/CalculateShippingFee.cs <<'EOF'
